import React, { useState, useEffect, useRef } from "react";
import { Box, Grid, Skeleton } from "@mui/material";
import Accordion from "components/Accordion";
import FormInputSelect from "components/form/FormInputSelect";
import SignatureCanvas from "react-signature-canvas";

const Signature = ({
  control,
  CMCOLoading,
  CMCO,
  sigCanvas,
  applicationSignatures,
  updateAvailableFlag,
}) => {
  const [signatureUrl, setSignatureUrl] = useState("");
  const fileInputRef = useRef(null); // Reference for hidden file input

  useEffect(() => {
    if (applicationSignatures?.length > 0) {
      const foundSignature = applicationSignatures.find(
        (sig) => sig.cmco_signature !== ""
      );
      if (foundSignature && sigCanvas.current) {
        sigCanvas.current.fromDataURL(foundSignature.cmco_signature);
        setSignatureUrl(foundSignature.cmco_signature);
      }
    }
  }, [applicationSignatures, sigCanvas]);

  const handleClear = () => {
    sigCanvas.current.clear();
    setSignatureUrl("");
  };

  const handleFileUpload = (e) => {
    const file = e.target.files[0];
    if (file && file.type.startsWith("image/")) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const dataUrl = reader.result;
        sigCanvas.current.clear();
        sigCanvas.current.fromDataURL(dataUrl);
        setSignatureUrl(dataUrl);
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <Accordion title="CMCO Signature">
      <Box sx={{ mt: 1 }}>
        <Grid
          container
          spacing={2}
          justifyContent="flex-start"
          alignItems="flex-start"
        >
          {/* Left Side - CMCO Name */}
          <Grid
            container
            item
            spacing={2}
            xs={12}
            sm={6}
            justifyContent="flex-start"
            alignItems="flex-start"
          >
            <Grid item xs={12}>
              {CMCOLoading ? (
                <Skeleton variant="rectangular" height={37.13} />
              ) : (
                <FormInputSelect
                  control={control}
                  options={CMCO}
                  getOptionLabel={(option) => option?.user_name}
                  id="id"
                  name="cmco_id"
                  label="CMCO Name"
                  disabled
                />
              )}
            </Grid>
          </Grid>

          {/* Right Side - Signature Area */}
          <Box sx={{ border: 1, ml: 8, mt: 2 }}>
            <SignatureCanvas
              ref={sigCanvas}
              penColor="black"
              backgroundColor="white"
              canvasProps={{
                width: 500,
                height: 200,
                className: "signature-canvas",
                style: { border: "1px solid black" },
              }}
            />
            <br />
            <button onClick={handleClear}>Clear</button>
            {updateAvailableFlag && (
              <>
                <button
                  onClick={() => fileInputRef.current.click()}
                  style={{ marginLeft: "10px" }}
                >
                  Browse
                </button>
                <input
                  type="file"
                  accept="image/*"
                  onChange={handleFileUpload}
                  ref={fileInputRef}
                  style={{ display: "none" }}
                />
              </>
            )}
          </Box>
        </Grid>
      </Box>
    </Accordion>
  );
};

export default React.memo(Signature);
